package ro.leo.visual;
import java.io.*;import java.nio.*;import java.nio.charset.*;import java.util.*;
/** UTF-8 CSV/TSV with quoted fields; bounded to two-column learning data. */
final class PocketTable {
 static List<String[]> parse(byte[] bytes,int limit)throws Exception{if(bytes.length>2*1024*1024)throw new IOException("Import limit: 2 MiB");String text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString().replace("\uFEFF","");char sep=text.indexOf('\t')>=0?'\t':text.substring(0,Math.max(0,text.indexOf('\n')<0?text.length():text.indexOf('\n'))).contains(";")?';':',';ArrayList<String[]> rows=new ArrayList<>();ArrayList<String> row=new ArrayList<>();StringBuilder cell=new StringBuilder();boolean quote=false;for(int i=0;i<=text.length();i++){char ch=i==text.length()?'\n':text.charAt(i);if(ch=='"'){if(quote&&i+1<text.length()&&text.charAt(i+1)=='"'){cell.append('"');i++;}else if(quote)quote=false;else if(cell.length()==0)quote=true;else throw new IOException("Invalid quote");}else if(!quote&&(ch==sep||ch=='\n'||ch=='\r')){row.add(cell.toString().trim());cell.setLength(0);if(ch!=sep){if(ch=='\r'&&i+1<text.length()&&text.charAt(i+1)=='\n')i++;if(row.size()==1&&row.get(0).isEmpty()){row.clear();continue;}if(row.size()!=2||row.get(0).isEmpty()||row.get(1).isEmpty())throw new IOException("Expected two nonempty columns");rows.add(row.toArray(new String[0]));row.clear();if(rows.size()>limit)throw new IOException("Too many rows");}}else{cell.append(ch);if(cell.length()>4096)throw new IOException("Cell too long");}}if(quote)throw new IOException("Unclosed quote");return rows;}
 static String fold(String s){return java.text.Normalizer.normalize(s,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.ROOT);}
}
